import{_ as a,o as i,c as n,ag as e}from"./chunks/framework.CU0NaXTj.js";const o=JSON.parse('{"title":"「布局技巧」图片未加载前自动撑开元素高度","description":"","frontmatter":{"title":"「布局技巧」图片未加载前自动撑开元素高度","date":"2020-02-22T16:37:10.000Z","permalink":"/pages/3d52574260725aea","categories":["前端","CSS"],"tags":[null],"author":{"name":"dazaer007","link":"https://github.com/xugaoyi"}},"headers":[],"relativePath":"01.前端/11.CSS/20.「布局技巧」图片未加载前自动撑开元素高度.md","filePath":"01.前端/11.CSS/20.「布局技巧」图片未加载前自动撑开元素高度.md","lastUpdated":1774415064000}'),p={name:"01.前端/11.CSS/20.「布局技巧」图片未加载前自动撑开元素高度.md"};function t(l,s,h,r,d,k){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="「布局技巧」图片未加载前自动撑开元素高度" tabindex="-1">「布局技巧」图片未加载前自动撑开元素高度 <a class="header-anchor" href="#「布局技巧」图片未加载前自动撑开元素高度" aria-label="Permalink to &quot;「布局技巧」图片未加载前自动撑开元素高度&quot;">​</a></h1><p>在移动端开发中，有一些元素是根据图片高度来自动撑开的 ，高度不能写死（如轮播图的外层元素）。在网络较慢的情况下，图片加载需要一些时间，此时该元素的高度没有被撑开，在网页布局上会有一些不想看到的效果。</p><p>这种情况我们可以设置如下样式来设置该元素的高度：</p><div class="language-stylus vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">stylus</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.wrapper</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  overflow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> hidden</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  width</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  height</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  padding-bottom</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 26.66</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 这个数值是图片的高宽比，即 高/宽</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  background</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> #eee</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>上面代码中，<code>padding-bottom</code> 的取值是图片的高宽比（即，高/宽），它会根据 <code>width</code>值的<code>26.66%</code>计算，最终元素的高度会和图片加载完成后的高度一致。</p><p>也可以使用<code>vw</code>的方法，但在一些浏览器可能有兼容性问题：</p><div class="language-stylus vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">stylus</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.wrapper</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  width</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  height</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 26.66</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">vw</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  background</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> #eee</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p><code>vw</code>，viewpoint width，视窗宽度，1vw=视窗宽度的1%</p><p><code>vh</code>，viewpoint height，视窗高度，1vh=视窗高度的1%</p><p>更多 <a href="https://www.runoob.com/cssref/css-units.html" target="_blank" rel="noreferrer">CSS单位</a>。</p></blockquote>`,8)])])}const g=a(p,[["render",t]]);export{o as __pageData,g as default};
